-- ============================================================
-- PetStore 宠物商店 CMS —— 建表脚本（H2，MODE=MySQL）
-- 参照 JPetStore 经典建模 + 课程要求（account 含 admin 标记、item 含库存与状态）
-- 约定：
--   1) 表名/列名全小写，实体侧靠 map-underscore-to-camel-case 映射到驼峰属性
--   2) 金额统一用 DECIMAL(10,2)，不用 FLOAT
--   3) 主键用 GENERATED BY DEFAULT AS IDENTITY（H2 写法，MySQL 模式可接受）
--   4) orders 是 SQL 保留字，但 H2 MySQL 模式下不加引号可直接使用（已实测通过）
-- ============================================================

DROP TABLE IF EXISTS lineitem;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS order_status;
DROP TABLE IF EXISTS item;
DROP TABLE IF EXISTS product;
DROP TABLE IF EXISTS category;
DROP TABLE IF EXISTS account;

-- ---------- 1. 用户 ----------
CREATE TABLE account (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- 用户主键
    username      VARCHAR(50)  NOT NULL,                                     -- 登录名
    password      VARCHAR(100) NOT NULL,                                     -- 口令（实验中明文/哈希均未接入，仅占位）
    email         VARCHAR(100) NOT NULL,                                     -- 邮箱
    first_name    VARCHAR(50),                                               -- 名
    last_name     VARCHAR(50),                                               -- 姓
    phone         VARCHAR(30),                                               -- 电话
    address       VARCHAR(255),                                              -- 地址
    city          VARCHAR(50),
    state         VARCHAR(50),
    zip           VARCHAR(20),
    country       VARCHAR(50),
    status        VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',                    -- ACTIVE / DISABLED
    admin         BOOLEAN      NOT NULL DEFAULT FALSE,                       -- 是否管理员（后台管理入口用）
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_account_username UNIQUE (username),
    CONSTRAINT uk_account_email UNIQUE (email)
);
CREATE INDEX idx_account_admin ON account (admin);

-- ---------- 2. 分类 ----------
CREATE TABLE category (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    catid         VARCHAR(20)  NOT NULL,                                     -- 业务编号，如 DOGS
    name          VARCHAR(50)  NOT NULL,                                     -- 中文名，如 犬类
    description   VARCHAR(255),                                              -- 描述
    sort_order    INTEGER      NOT NULL DEFAULT 0,                           -- 展示排序
    CONSTRAINT uk_category_catid UNIQUE (catid)
);
CREATE INDEX idx_category_sort ON category (sort_order);

-- ---------- 3. 商品 ----------
CREATE TABLE product (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    productid     VARCHAR(30)  NOT NULL,                                     -- 业务编号，如 DOG-001
    category_id   INTEGER      NOT NULL,                                     -- 所属分类
    name          VARCHAR(100) NOT NULL,                                     -- 商品名
    description   VARCHAR(500),                                              -- 商品描述
    image_path    VARCHAR(255),                                              -- 图片路径：/images/products/<文件名>.png
    list_price    DECIMAL(10,2) NOT NULL DEFAULT 0.00,                       -- 参考价（item 单价以 item 为准）
    status        VARCHAR(20)  NOT NULL DEFAULT 'ON_SALE',                   -- ON_SALE / OFF_SHELF
    sort_order    INTEGER      NOT NULL DEFAULT 0,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_product_productid UNIQUE (productid),
    CONSTRAINT fk_product_category FOREIGN KEY (category_id) REFERENCES category (id)
);
CREATE INDEX idx_product_category ON product (category_id);
CREATE INDEX idx_product_status ON product (status);

-- ---------- 4. 商品 SKU（item） ----------
CREATE TABLE item (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    itemid        VARCHAR(30)  NOT NULL,                                     -- SKU 编号，如 EST-1
    product_id    INTEGER      NOT NULL,                                     -- 所属商品
    name          VARCHAR(100) NOT NULL,                                     -- 规格名，如 1kg 装
    description   VARCHAR(500),
    list_price    DECIMAL(10,2) NOT NULL,                                    -- 单价
    unit_cost     DECIMAL(10,2) NOT NULL DEFAULT 0.00,                       -- 成本价
    quantity      INTEGER      NOT NULL DEFAULT 0,                           -- 库存
    status        VARCHAR(20)  NOT NULL DEFAULT 'INSTOCK',                   -- INSTOCK / OUTOFSTOCK / DISCONTINUED
    image_path    VARCHAR(255),                                              -- 图片路径：/images/products/<文件名>.png
    CONSTRAINT uk_item_itemid UNIQUE (itemid),
    CONSTRAINT fk_item_product FOREIGN KEY (product_id) REFERENCES product (id)
);
CREATE INDEX idx_item_product ON item (product_id);
CREATE INDEX idx_item_status ON item (status);

-- ---------- 5. 订单状态字典 ----------
CREATE TABLE order_status (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code          VARCHAR(20)  NOT NULL,                                     -- P / C / D ...（JPetStore 风格）
    name          VARCHAR(30)  NOT NULL,                                     -- 中文状态名
    description   VARCHAR(255),
    sort_order    INTEGER      NOT NULL DEFAULT 0,
    CONSTRAINT uk_order_status_code UNIQUE (code)
);

-- ---------- 6. 订单 ----------
CREATE TABLE orders (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    orderid       INTEGER      NOT NULL,                                     -- 业务单号（JPetStore 起始 1000）
    account_id    INTEGER      NOT NULL,                                     -- 下单用户
    status_id     INTEGER      NOT NULL,                                     -- 订单状态
    order_date    DATE         NOT NULL,                                     -- 下单日期
    ship_address  VARCHAR(255),                                              -- 收货地址
    ship_city     VARCHAR(50),
    ship_state    VARCHAR(50),
    ship_zip      VARCHAR(20),
    ship_country  VARCHAR(50),
    total_price   DECIMAL(10,2) NOT NULL DEFAULT 0.00,                        -- 订单总额（由明细汇总）
    CONSTRAINT uk_orders_orderid UNIQUE (orderid),
    CONSTRAINT fk_orders_account FOREIGN KEY (account_id) REFERENCES account (id),
    CONSTRAINT fk_orders_status FOREIGN KEY (status_id) REFERENCES order_status (id)
);
CREATE INDEX idx_orders_account ON orders (account_id);
CREATE INDEX idx_orders_status ON orders (status_id);
CREATE INDEX idx_orders_date ON orders (order_date);

-- ---------- 7. 订单明细 ----------
CREATE TABLE lineitem (
    id            INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id      INTEGER      NOT NULL,                                     -- 所属订单
    item_id       INTEGER      NOT NULL,                                     -- SKU
    quantity      INTEGER      NOT NULL,                                     -- 数量
    unit_price    DECIMAL(10,2) NOT NULL,                                    -- 下单时的成交单价（快照，别随 item 改价而变）
    CONSTRAINT fk_lineitem_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_lineitem_item FOREIGN KEY (item_id) REFERENCES item (id),
    CONSTRAINT ck_lineitem_quantity CHECK (quantity > 0)
);
CREATE INDEX idx_lineitem_order ON lineitem (order_id);
CREATE INDEX idx_lineitem_item ON lineitem (item_id);
